#!/usr/bin/env bash
# 「装」页底部第二轮：更有创意的三个方向（GPT Image，在真实底部截图上改）
#   bash docs/mockups/bottom/gen.sh
set -u
cd "$(dirname "$0")"
G=~/.claude/skills/multimodal-extension/scripts/gpt_image.py
KEEP='Edit this real website screenshot: the bottom part of a Chinese fitness meal-planning website page (an "open dataset" section about the estimated nutrition of 44 McDonald'"'"'s China burger ingredients, then the site footer). Completely redesign this bottom area with a much more creative, memorable idea as described below, in the site style: warm cream paper #F3EFE6, near-black ink #17150F, accent red #D23A1E used sparingly, heavy bold Chinese headings, condensed numerals, a red felt-tip "coach annotation" pen layer where it fits. The three site mascots may appear: a fried chicken drumstick, a double cheeseburger and a chicken nugget, cute 3D characters with red-white sweatbands and white sneakers. Use ONLY the Chinese/English texts listed in the direction, exactly as written; no other text. Strictly NO McDonald'"'"'s logo, golden arches, brand packaging or cups; NO neon, glow, cyberpunk, glassmorphism; NO emoji. Desktop web page, landscape 3:2, opaque.'
gen() { python3 "$G" --input base-bottom.png --background opaque --size 1536x1024 --quality high --output "$1.png" --prompt "$KEEP Direction: $2" > "$1.log" 2>&1; echo "done $1"; }

gen n1-map "Ingredient map + curtain-call footer. The dataset section is one big elegant scatter plot titled 开放数据集 with the subtitle 44 种配料，一张图看懂为什么只吃馅. X axis label 热量（大卡） from 0 to 400, Y axis label 蛋白质（g） from 0 to 25, light grid, faint diagonal guide lines. About 44 small ink dots with thin horizontal error bars, in clear clusters: meats in the upper area (several between 90 and 390 kcal with 7 to 24 g protein), breads as a low flat cluster at 137 to 209 kcal with only 4 to 7 g protein, sauces lying on the bottom axis between 0 and 132 kcal with almost 0 g, vegetables at the origin. A red felt-tip pen loosely circles three clusters with short handwritten red notes: 肉：蛋白主力，吃掉 / 面包：留到明早 / 酱：几乎只有热量. A solid ink pill button 下载 ingredient_library.json under the chart. The footer below is a curtain call: the three mascots stand in a row on the footer baseline, each holding a small sign: 练 点餐方案 / 拆 只吃馅 / 装 WorkBuddy; beside them the brand Gyᗰ 麦门健身房 and one small line 本项目是麦当劳程序员节创意开发大赛的参赛作品，不是麦当劳官方产品，数字均为估算 and MIT License · GitHub." &
gen n2-label "Nutrition-facts label. The dataset is presented as a big, beautifully typeset food-package nutrition label (thick black rules, bold header, tidy rows, like the back of a snack package), centered on the page, slightly rotated by 1 degree with a soft shadow, with the header 营养成分表 and the rows exactly: 配料 · 44 种 / 营养项目 · 热量 蛋白质 脂肪 碳水 钠 钙 / 误差 · 每一项都有 / 来源 · 28 款官方整份营养 + 配方联合求解 / 净含量 · 34 KB / 执行标准 · MIT License / 生产商 · Gyᗰ 麦门健身房 / 产地 · GitHub. At the bottom of the label a real-looking black barcode with the digits text maimen-gym under it. Next to the label, a solid ink pill button 下载 ingredient_library.json and a small red handwritten coach note 照着这张表拆汉堡 with a curved arrow pointing at the label. The footer below is styled as the package fine print: small text 本项目是麦当劳程序员节创意开发大赛的参赛作品，不是麦当劳官方产品，数字均为估算 and links 练 点餐方案 · 拆 只吃馅 · 装 WorkBuddy · GitHub." &
gen n3-report "Gym body-composition report + membership card. The dataset section looks like a printed gym body-composition (InBody-style) report sheet on white paper with a thin border, titled 配料体测报告, subtitle 每 100 大卡含多少蛋白质. Horizontal bar rows over a segmented scale labelled 低 / 标准 / 高, exactly these rows and values: 小牛肉饼 9.0 g / 鳕鱼排 9.0 g / 圆形煎蛋 8.9 g / 安格斯牛肉饼 8.7 g / 普通汉堡面包 3.2 g / 麦香鸡酱 0 g; the top four bars long and ink, the bread short, the sauce empty; a red pen circle around the bread and sauce rows with the handwritten note 只吃馅的理由. Small print on the sheet: 共 44 种配料 · 误差每项都有 · JSON 34 KB. A solid ink pill button 下载 ingredient_library.json beside the sheet. The footer is a horizontal gym membership card (rounded rectangle, cream with an ink stripe) reading Gyᗰ 麦门健身房 会员卡, with the line 会员号 maimen-gym, the links 练 点餐方案 / 拆 只吃馅 / 装 WorkBuddy, a small barcode, and the chicken nugget mascot photo in the card; under the card one small line 本项目是麦当劳程序员节创意开发大赛的参赛作品，不是麦当劳官方产品，数字均为估算 · MIT License." &
